-- =====================================================================
-- PAYMENTS DB (TDD §9.6), Oracle flavour.
-- Ids are generated by the application (UUID stored as RAW(16)).
-- JSON documents are stored as VARCHAR2 text.
-- =====================================================================
CREATE TABLE payment_intents (
    id                 RAW(16) PRIMARY KEY,
    order_id           RAW(16) NOT NULL,
    customer_id        RAW(16) NOT NULL,
    amount             NUMBER(19,4) NOT NULL CHECK (amount > 0),
    currency           CHAR(3) NOT NULL,
    provider           VARCHAR2(20) NOT NULL CHECK (provider IN ('STRIPE','RAZORPAY')),
    provider_intent_id VARCHAR2(120),
    status             VARCHAR2(30) DEFAULT 'INITIATED' NOT NULL
                       CHECK (status IN ('INITIATED','REQUIRES_ACTION','AUTHORIZED','CAPTURED','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED')),
    idempotency_key    VARCHAR2(80) NOT NULL,
    failure_code       VARCHAR2(60),
    failure_message    VARCHAR2(500),
    version            NUMBER(19) DEFAULT 0 NOT NULL,
    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_pi_idempotency_key UNIQUE (idempotency_key),
    -- Stripe pi_* and Razorpay order_* ids never collide, so a single-column unique is enough. A composite
    -- (provider, provider_intent_id) would reject two intents whose provider id is still NULL on Oracle.
    CONSTRAINT uq_pi_provider_intent UNIQUE (provider_intent_id)
);
CREATE INDEX idx_pi_order ON payment_intents (order_id);
CREATE INDEX idx_pi_customer ON payment_intents (customer_id, created_at);
CREATE INDEX idx_pi_status_updated ON payment_intents (status, updated_at);

CREATE TABLE payment_attempts (
    id                 RAW(16) PRIMARY KEY,
    intent_id          RAW(16) NOT NULL REFERENCES payment_intents(id) ON DELETE CASCADE,
    attempt_no         NUMBER(10) NOT NULL,
    provider_charge_id VARCHAR2(120),
    status             VARCHAR2(30) NOT NULL,
    raw_response       VARCHAR2(32767),
    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_attempt_no UNIQUE (intent_id, attempt_no)
);

CREATE TABLE refunds (
    id                 RAW(16) PRIMARY KEY,
    intent_id          RAW(16) NOT NULL REFERENCES payment_intents(id),
    order_id           RAW(16) NOT NULL,
    amount             NUMBER(19,4) NOT NULL CHECK (amount > 0),
    currency           CHAR(3) NOT NULL,
    reason             VARCHAR2(200),
    status             VARCHAR2(30) DEFAULT 'INITIATED' NOT NULL
                       CHECK (status IN ('INITIATED','PROCESSING','SUCCESS','FAILED')),
    provider_refund_id VARCHAR2(120),
    idempotency_key    VARCHAR2(80) NOT NULL,
    version            NUMBER(19) DEFAULT 0 NOT NULL,
    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    completed_at       TIMESTAMP WITH TIME ZONE,
    CONSTRAINT uq_refund_idempotency_key UNIQUE (idempotency_key)
);
CREATE INDEX idx_refund_order ON refunds (order_id);
CREATE INDEX idx_refund_intent ON refunds (intent_id);
CREATE INDEX idx_refund_provider_ref ON refunds (provider_refund_id);

CREATE TABLE webhook_events (
    id                RAW(16) PRIMARY KEY,
    provider          VARCHAR2(20) NOT NULL,
    provider_event_id VARCHAR2(120) NOT NULL,
    event_type        VARCHAR2(60) NOT NULL,
    payload           VARCHAR2(32767) NOT NULL,
    signature_valid   BOOLEAN NOT NULL,
    processed_at      TIMESTAMP WITH TIME ZONE,
    received_at       TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_webhook_event UNIQUE (provider, provider_event_id)
);
CREATE INDEX idx_webhook_unprocessed ON webhook_events (processed_at, received_at);

CREATE TABLE payouts (
    id           RAW(16) PRIMARY KEY,
    supplier_id  RAW(16) NOT NULL,
    period_start DATE NOT NULL,
    period_end   DATE NOT NULL,
    gross_amount NUMBER(19,4) NOT NULL,
    commission   NUMBER(19,4) NOT NULL,
    net_amount   NUMBER(19,4) NOT NULL,
    status       VARCHAR2(30) DEFAULT 'PENDING' NOT NULL,
    payout_ref   VARCHAR2(120),
    created_at   TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX idx_payouts_supplier ON payouts (supplier_id, period_start);

CREATE TABLE payment_outbox (
    id           NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    aggregate_id RAW(16) NOT NULL,
    event_type   VARCHAR2(60) NOT NULL,
    payload      VARCHAR2(32767) NOT NULL,
    status       VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    sent_at      TIMESTAMP WITH TIME ZONE
);
CREATE INDEX idx_pay_outbox_pending ON payment_outbox (status, created_at);
